    Bug 1916854 - Fix calendar printing. r=mkmelin

    Fixed so that we actually print something, and some L10n nits.

    Differential Revision: https://phabricator.services.mozilla.com/D221089

diff --git a/calendar/base/content/calendar-print.js b/calendar/base/content/calendar-print.js
index 00932b0028c..fd4abb24b15 100644
--- a/calendar/base/content/calendar-print.js
+++ b/calendar/base/content/calendar-print.js
@@ -29,6 +29,8 @@ const { cal } = ChromeUtils.importESModule("resource:///modules/calendar/calUtil
     link.href = href;
   }

+  document.l10n.addResourceIds(["calendar/calendar.ftl"]);
+
   const otherForm = document.querySelector("form");
   otherForm.hidden = true;

diff --git a/calendar/base/modules/utils/calPrintUtils.sys.mjs b/calendar/base/modules/utils/calPrintUtils.sys.mjs
index afdc87f828e..d7337d3c032 100644
--- a/calendar/base/modules/utils/calPrintUtils.sys.mjs
+++ b/calendar/base/modules/utils/calPrintUtils.sys.mjs
@@ -596,7 +596,7 @@ const weekPlannerView = {
 Services.obs.addObserver(
   {
     async observe(subDialogWindow) {
-      if (!subDialogWindow.location.href.startsWith("chrome://global/content/print.html?")) {
+      if (!subDialogWindow.location.href.startsWith("chrome://global/content/print.html")) {
         return;
       }

diff --git a/calendar/locales/en-US/calendar/calendar.ftl b/calendar/locales/en-US/calendar/calendar.ftl
index fdec0c82e0a..6142717a80b 100644
--- a/calendar/locales/en-US/calendar/calendar.ftl
+++ b/calendar/locales/en-US/calendar/calendar.ftl
@@ -539,7 +539,7 @@ event-details-end-date = End:
 datetime-with-timezone = { $datetime }, { $timezone }

 # LOCALIZATION NOTE (single-long-calendar-week):
-# used for display of calendar weeks in short form like 'Calendar Week 43'
+# used for display of calendar weeks in long form like 'Calendar Week 43'
 #    $index will be replaced with the index of the week
 single-long-calendar-week = Calendar Week: { $index }

@@ -549,6 +549,12 @@ single-long-calendar-week = Calendar Week: { $index }
 single-calendar-week = CW: { $index }
     .title = Calendar Week: { $index }

+# LOCALIZATION NOTE (several-long-calendar-weeks):
+# used for display of calendar weeks in long form like 'Calendar Weeks 43 - 45'
+#    $startIndex will be replaced with the index of the start-week
+#    $endIndex will be replaced with the index of the end-week
+several-long-calendar-weeks = Calendar Weeks { $startIndex }-{ $endIndex }
+
 # LOCALIZATION NOTE (several-calendar-weeks):
 # used for display of calendar weeks in short form like 'CWs 43 - 45'
 #    $startIndex will be replaced with the index of the start-week
